import React, { useState, useEffect, useRef } from 'react';
import { Send, X, User, Clock, MoreVertical, Edit, Trash2, Paperclip, Copy } from 'lucide-react';

const ChatWindow = ({ 
  conversation, 
  messages, 
  loading, 
  onSendMessage, 
  onClose,
  isAdmin,
  user 
}) => {
  const [inputMessage, setInputMessage] = useState('');
  const [sending, setSending] = useState(false);
  const [showMenuForMessage, setShowMenuForMessage] = useState(null);
  const messagesEndRef = useRef(null);

  // Fonction pour obtenir le nom de l'autre utilisateur avec les bons champs
  const getOtherUserName = () => {
    if (isAdmin) {
      // Pour les admins: afficher le nom de l'utilisateur
      // Vérifier tous les champs possibles retournés par l'API
      const name = conversation.user_first_name && conversation.user_last_name 
        ? `${conversation.user_first_name} ${conversation.user_last_name}`
        : conversation.first_name && conversation.last_name
        ? `${conversation.first_name} ${conversation.last_name}`
        : conversation.user_name || conversation.name || 'Utilisateur';
      return name.trim();
    } else {
      // Pour les utilisateurs: afficher le nom de l'admin
      const name = conversation.admin_first_name && conversation.admin_last_name
        ? `${conversation.admin_first_name} ${conversation.admin_last_name}`
        : conversation.admin_name || 'Conseiller';
      return name.trim();
    }
  };

  // Fonction pour obtenir l'email de l'autre utilisateur
  const getOtherUserEmail = () => {
    if (isAdmin) {
      return conversation.user_email || conversation.email || '';
    }
    return conversation.admin_email || '';
  };

  // Fonction pour obtenir l'avatar/initiales
  const getAvatarInitials = () => {
    const name = getOtherUserName();
    if (!name) return '?';
    const names = name.split(' ');
    if (names.length >= 2) {
      return (names[0].charAt(0) + names[names.length - 1].charAt(0)).toUpperCase();
    }
    return name.charAt(0).toUpperCase();
  };

  // Fonction pour envoyer un message
  const handleSend = async () => {
    if (!inputMessage.trim() || sending) return;

    try {
      setSending(true);
      await onSendMessage(conversation.id, inputMessage.trim());
      setInputMessage('');
    } catch (error) {
      console.error('Erreur envoi message:', error);
    } finally {
      setSending(false);
    }
  };

  // Fonction pour gérer la touche Entrée
  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  // Fonction pour scroller vers le bas
  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  // Fonction pour formater l'heure
  const formatTime = (dateString) => {
    try {
      const date = new Date(dateString);
      return date.toLocaleTimeString('fr-FR', { 
        hour: '2-digit', 
        minute: '2-digit' 
      });
    } catch {
      return '--:--';
    }
  };

  // Fonctions pour les actions sur les messages
  const handleEditMessage = (message) => {
    console.log('Modifier le message:', message);
    setInputMessage(message.content);
    setShowMenuForMessage(null);
  };

  const handleDeleteMessage = (message) => {
    console.log('Supprimer le message:', message);
    // Ici, vous appellerez votre API pour supprimer le message
    setShowMenuForMessage(null);
  };

  const handleCopyMessage = (message) => {
    navigator.clipboard.writeText(message.content);
    console.log('Message copié:', message.content);
    setShowMenuForMessage(null);
  };

  // Scroller vers le bas quand les messages changent
  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Afficher le contenu de la conversation pour debug
  useEffect(() => {
    console.log('💬 Conversation data:', conversation);
    console.log('👤 User role:', isAdmin ? 'admin' : 'user');
    console.log('📝 Other user name:', getOtherUserName());
  }, [conversation]);

  return (
    <div className="bg-gradient-to-br from-white to-white/95 dark:from-neutral-900 dark:to-neutral-900/95 rounded-2xl shadow-2xl border border-white/30 dark:border-neutral-800/50 h-[600px] flex flex-col overflow-hidden">

      {/* Header */}
      <div className="p-4 sm:p-5 border-b border-neutral-200/50 dark:border-neutral-800/50 bg-white/80 dark:bg-neutral-900/80">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center text-white font-bold shadow-lg">
              {getAvatarInitials()}
            </div>
            <div className="min-w-0">
              <h3 className="font-bold text-lg text-neutral-900 dark:text-white truncate">
                {getOtherUserName()}
              </h3>
              <div className="flex items-center gap-2 mt-0.5">
                <div className="flex items-center gap-1 flex-shrink-0">
                  <div className="h-2 w-2 rounded-full bg-green-500"></div>
                  <span className="text-xs text-neutral-500 dark:text-neutral-400">En ligne</span>
                </div>
                {getOtherUserEmail() && (
                  <>
                    <span className="text-neutral-300 dark:text-neutral-700 flex-shrink-0">•</span>
                    <span className="text-xs text-neutral-500 dark:text-neutral-400 truncate">
                      {getOtherUserEmail()}
                    </span>
                  </>
                )}
              </div>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors flex-shrink-0"
          >
            <X className="w-5 h-5 text-neutral-500" />
          </button>
        </div>
      </div>

      {/* Zone des messages */}
      <div className="flex-1 overflow-y-auto p-4">
        {loading ? (
          <div className="flex flex-col items-center justify-center h-full">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500 mb-3"></div>
            <p className="text-neutral-500">Chargement des messages...</p>
          </div>
        ) : !messages || messages.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-center p-6">
            <div className="h-16 w-16 rounded-xl bg-gradient-to-r from-primary-500/10 to-secondary-500/10 flex items-center justify-center mx-auto mb-4">
              <MessageSquare className="h-8 w-8 text-primary-500/50" />
            </div>
            <p className="text-neutral-500 dark:text-neutral-400">
              Aucun message. Commencez la conversation !
            </p>
            <p className="text-xs text-neutral-400 dark:text-neutral-500 mt-2">
              Avec {getOtherUserName()}
            </p>
          </div>
        ) : (
          <div className="space-y-3">
            {messages.map((message) => {
              const isCurrentUser = message.sender_id === user?.id;

              return (
                <div
                  key={message.id}
                  className={`relative group ${isCurrentUser ? 'flex justify-end' : 'flex justify-start'}`}
                >
                  <div
                    className={`max-w-[85%] rounded-xl p-3 transition-all duration-200 ${
                      isCurrentUser
                        ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-br-none shadow-lg'
                        : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-900 dark:text-white rounded-bl-none'
                    }`}
                  >
                    {/* Contenu du message */}
                    <p className="text-sm leading-relaxed">{message.content}</p>

                    {/* Infos du message */}
                    <div className={`flex items-center justify-between mt-2 ${
                      isCurrentUser ? 'text-white/80' : 'text-neutral-500'
                    }`}>
                      <div className="flex items-center gap-1">
                        <Clock className="w-3 h-3" />
                        <span className="text-xs">{formatTime(message.created_at)}</span>
                      </div>

                      {/* Menu des actions (apparaît au survol pour les messages de l'utilisateur) */}
                      {isCurrentUser && (
                        <div className="relative">
                          <button
                            onClick={() => setShowMenuForMessage(showMenuForMessage === message.id ? null : message.id)}
                            className="opacity-0 group-hover:opacity-100 transition-opacity p-1 hover:bg-white/20 rounded"
                          >
                            <MoreVertical className="w-4 h-4" />
                          </button>

                          {/* Menu déroulant des actions */}
                          {showMenuForMessage === message.id && (
                            <div className="absolute right-0 top-full mt-1 w-32 bg-white dark:bg-neutral-800 rounded-lg shadow-xl border border-neutral-200 dark:border-neutral-700 z-10">
                              <button
                                onClick={() => handleEditMessage(message)}
                                className="w-full px-3 py-2 text-xs text-left hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-t-lg flex items-center gap-2"
                              >
                                <Edit className="w-3 h-3" />
                                Modifier
                              </button>
                              <button
                                onClick={() => handleCopyMessage(message)}
                                className="w-full px-3 py-2 text-xs text-left hover:bg-neutral-100 dark:hover:bg-neutral-700 flex items-center gap-2"
                              >
                                <Copy className="w-3 h-3" />
                                Copier
                              </button>
                              <button
                                onClick={() => handleDeleteMessage(message)}
                                className="w-full px-3 py-2 text-xs text-left hover:bg-red-50 dark:hover:bg-red-900/20 text-red-500 rounded-b-lg flex items-center gap-2"
                              >
                                <Trash2 className="w-3 h-3" />
                                Supprimer
                              </button>
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}

            <div ref={messagesEndRef} />
          </div>
        )}
      </div>

      {/* Zone de saisie */}
      <div className="p-4 border-t border-neutral-200/50 dark:border-neutral-800/50 bg-white/80 dark:bg-neutral-900/80">
        <div className="flex items-center gap-2">
          <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors">
            <Paperclip className="w-5 h-5 text-neutral-500" />
          </button>

          <div className="flex-1">
            <input
              type="text"
              value={inputMessage}
              onChange={(e) => setInputMessage(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder={`Envoyer un message à ${getOtherUserName()}...`}
              className="w-full px-4 py-3 bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              disabled={sending}
            />
          </div>

          <button
            onClick={handleSend}
            disabled={!inputMessage.trim() || sending}
            className="p-3 rounded-xl bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg"
          >
            {sending ? (
              <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
            ) : (
              <Send className="w-5 h-5" />
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

// Icône MessageSquare
const MessageSquare = ({ className }) => (
  <svg className={className} fill="none" stroke="currentColor" viewBox="0 0 24 24">
    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
  </svg>
);

export default ChatWindow;
